def transform(grid):
    from collections import Counter
    sep = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = []
    for r, row in enumerate(grid):
        if row.count(sep) * 2 > len(row):
            for c, v in enumerate(row):
                if v != sep:
                    points.append((r, c))
    for c in range(len(grid[0])):
        col = [row[c] for row in grid]
        if col.count(sep) * 2 > len(col):
            for r, v in enumerate(col):
                if v != sep:
                    points.append((r, c))
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    return [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
